'use client'

import { AlertTriangle, Check, Circle, Lock } from 'lucide-react'

import { formatDateTime } from '@/lib/handshake/format'
import { SETTLEMENT_STATES, type Settlement, type SettlementState } from '@/lib/handshake/types'

/**
 * Settlement lifecycle visualization.
 *
 * Stages mirror the coordinator's actual path in `HandshakeASC`:
 *
 *   PREPARE → READY → FRESH VERIFICATION → COMMIT → SETTLED
 *
 * "Fresh verification" is the bounded window between `Ready` and `commit`:
 * `commit` reverts with `CommitWindowExpired` once `readyTime + TIMEOUT` passes,
 * so the settlement must be re-checked as still-valid inside that window. It is
 * a real gate, not decoration.
 *
 * The HELD branch replaces everything from the point of failure onward, because
 * a held settlement never reaches COMMIT — that is the invariant the whole
 * protocol rests on.
 */

type StageStatus = 'done' | 'current' | 'pending' | 'failed'

interface Stage {
  key: string
  name: string
  note: string
  status: StageStatus
  timestamp: number | null
}

function stageIcon(status: StageStatus) {
  if (status === 'done') return <Check size={11} />
  if (status === 'failed') return <AlertTriangle size={11} />
  if (status === 'current') return <Circle size={9} />
  return <Circle size={7} />
}

function buildStages(settlement: Settlement): Stage[] {
  const { state } = settlement
  const index = SETTLEMENT_STATES.indexOf(state)
  const reached = (target: SettlementState) => index >= SETTLEMENT_STATES.indexOf(target)

  if (state === 'HELD') {
    // Locate the failure point. `evidenceManifest` is written only by
    // `submitProofs`, so its presence means READY was reached and COMMIT
    // timed out instead.
    const reachedReady = Boolean(settlement.evidenceManifest)
    const bothPrepared = settlement.attestedLeg.prepared && settlement.nativeLeg.prepared

    return [
      {
        key: 'prepare',
        name: 'Prepare',
        note: bothPrepared
          ? 'Both legs registered locks under this settlement id.'
          : 'Only one leg was registered. The dual-PREPARE gate was never satisfied.',
        status: 'done',
        timestamp: settlement.prepareTime || null,
      },
      {
        key: 'ready',
        name: 'Ready',
        note: reachedReady
          ? 'Both leg commitments were bound in a single attestation quorum.'
          : 'Not reached. READY requires both legs verified in one attestation quorum.',
        status: reachedReady ? 'done' : 'pending',
        timestamp: reachedReady ? settlement.readyTime || null : null,
      },
      {
        key: 'verification-failed',
        name: reachedReady ? 'Commit window expired' : 'Verification failed',
        note: reachedReady
          ? 'The bounded commit window closed before COMMIT was called.'
          : 'The required proofs were not accepted inside the PREPARE window.',
        status: 'failed',
        timestamp: null,
      },
      {
        key: 'held',
        name: 'Held',
        note:
          settlement.heldReason ??
          'Timeout reached without COMMIT. The unilateral refund path is open and needs no attestor cooperation.',
        status: 'failed',
        timestamp: null,
      },
    ]
  }

  const stages: Stage[] = [
    {
      key: 'prepare',
      name: 'Prepare',
      note:
        settlement.attestedLeg.prepared && settlement.nativeLeg.prepared
          ? 'Both legs locked under this settlement id. Locks remain fully reversible.'
          : 'Awaiting the counterparty leg. The dual-PREPARE gate is not yet satisfied.',
      status: reached('READY') ? 'done' : 'current',
      timestamp: settlement.prepareTime || null,
    },
    {
      key: 'ready',
      name: 'Ready',
      note: 'Both leg commitments verified in a single attestation quorum.',
      status: reached('COMMITTED') ? 'done' : reached('READY') ? 'current' : 'pending',
      timestamp: settlement.readyTime || null,
    },
    {
      key: 'fresh-verification',
      name: 'Fresh verification',
      note: `Bounded window of ${Math.round(settlement.timeoutSeconds / 60)} minutes in which COMMIT stays callable. Source-chain finality buffers must clear first.`,
      status: reached('COMMITTED') ? 'done' : reached('READY') ? 'current' : 'pending',
      timestamp: null,
    },
    {
      key: 'commit',
      name: 'Commit',
      note: 'Irreversible settlement authorization on Creditcoin. Nothing on a source chain becomes final before this point.',
      status: reached('SETTLED') ? 'done' : reached('COMMITTED') ? 'current' : 'pending',
      timestamp: null,
    },
    {
      key: 'settled',
      name: 'Settled',
      note: 'Both native legs delivered and the finalization attestation recorded.',
      status: state === 'SETTLED' ? 'done' : 'pending',
      timestamp: null,
    },
  ]

  return stages
}

export function SettlementTimeline({ settlement }: { settlement: Settlement }) {
  const stages = buildStages(settlement)

  return (
    <div className="ds-timeline">
      {stages.map((stage, index) => {
        const isLast = index === stages.length - 1
        const connectorStatus =
          stage.status === 'done' ? 'done' : stage.status === 'failed' ? 'failed' : undefined

        return (
          <div className="ds-stage" key={stage.key} data-status={stage.status}>
            <div className="ds-stage-rail">
              <span className="ds-stage-node" data-status={stage.status}>
                {stage.key === 'commit' && stage.status === 'done' ? (
                  <Lock size={10} />
                ) : (
                  stageIcon(stage.status)
                )}
              </span>
              {isLast ? null : <span className="ds-stage-connector" data-status={connectorStatus} />}
            </div>
            <div className="ds-stage-body">
              <div className="ds-stage-name">
                {stage.name}
                {stage.timestamp ? (
                  <span className="ds-stage-time">{formatDateTime(stage.timestamp)}</span>
                ) : null}
              </div>
              <p className="ds-stage-note">{stage.note}</p>
            </div>
          </div>
        )
      })}
    </div>
  )
}
